function minimumDifference(nums) {
  const n = nums.length / 2;
  const total = nums.reduce((sum, value) => sum + value, 0);
  const sumsBySize = (half) => {
    const groups = Array.from({ length: n + 1 }, () => []);
    for (let mask = 0; mask < 1 << n; mask++) {
      let sum = 0;
      let size = 0;
      for (let i = 0; i < n; i++) {
        if (mask & (1 << i)) {
          sum += half[i];
          size++;
        }
      }
      groups[size].push(sum);
    }
    return groups;
  };
  const leftSums = sumsBySize(nums.slice(0, n));
  const rightSums = sumsBySize(nums.slice(n));
  for (const group of rightSums) {
    group.sort((a, b) => a - b);
  }
  let best = Infinity;
  for (let size = 0; size <= n; size++) {
    const candidates = rightSums[n - size];
    for (const leftSum of leftSums[size]) {
      let low = 0;
      let high = candidates.length;
      while (low < high) {
        const mid = (low + high) >> 1;
        if (2 * (leftSum + candidates[mid]) < total) {
          low = mid + 1;
        } else {
          high = mid;
        }
      }
      if (low < candidates.length) {
        best = Math.min(best, Math.abs(total - 2 * (leftSum + candidates[low])));
      }
      if (low > 0) {
        best = Math.min(best, Math.abs(total - 2 * (leftSum + candidates[low - 1])));
      }
    }
  }
  return best;
}

