function minimumDifference(nums) {
  const n = nums.length / 2;
  let best = Infinity;
  // Place each number into the first or the second group, keeping both groups at most n long.
  const place = (index, firstCount, firstSum, secondSum) => {
    if (index === nums.length) {
      best = Math.min(best, Math.abs(firstSum - secondSum));
      return;
    }
    if (firstCount < n) place(index + 1, firstCount + 1, firstSum + nums[index], secondSum);
    if (index - firstCount < n) place(index + 1, firstCount, firstSum, secondSum + nums[index]);
  };
  place(0, 0, 0, 0);
  return best;
}

