function generate(rand, size) {
  const n = size === 'large' ? 13 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 5);
  const limit = 10000000;
  const style = rand();
  const value = () => {
    if (size === 'large' || style < 0.25) return Math.floor(rand() * (2 * limit + 1)) - limit;
    if (style < 0.35) return rand() < 0.5 ? -limit : limit;
    return Math.floor(rand() * 41) - 20;
  };
  return [Array.from({ length: 2 * n }, value)];
}
